#!/usr/bin/env node
// Read the miint_doctest_examples() table macro and emit one sqllogictest
// .test file per documented function under test/sql/_generated/. Each entry
// becomes a `statement ok` block that the existing run_tests.sh pipeline
// runs unmodified.
//
// Generated files are gitignored — re-run `npm run prebuild` after C++
// changes that add or remove `executable_examples` parameters.

import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, writeFileSync, rmSync, readdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '..', '..');
const DEFAULT_LOCAL_EXT = resolve(REPO_ROOT, 'build/release/extension/miint/miint.duckdb_extension');

const DUCKDB_BIN = process.env.DUCKDB_BIN ?? 'duckdb';
const MIINT_EXT = process.env.MIINT_EXT
  ?? (existsSync(DEFAULT_LOCAL_EXT) ? DEFAULT_LOCAL_EXT : null);
const OUT_DIR = resolve(REPO_ROOT, 'test/sql/doctests');

if (!MIINT_EXT) {
  // No local build — doctests can only be generated against an extension
  // that has miint_doctest_examples() (i.e. one built from this branch).
  // Released artifacts predate the doctest macro, so released-mode is a
  // no-op rather than an error.
  console.error('generate-doctests: skipped (no local extension build; released mode has no doctest macro)');
  process.exit(0);
}

const sql = `LOAD '${MIINT_EXT}'; SELECT function_name, sql FROM miint_doctest_examples() ORDER BY function_name, sql;`;
const res = spawnSync(DUCKDB_BIN, ['-unsigned', '-json', '-c', sql], {
  encoding: 'utf8',
  maxBuffer: 64 * 1024 * 1024,
});
if (res.status !== 0) {
  // Released artifacts (and any local build pre-doctest-support) don't
  // expose miint_doctest_examples(). Don't fail the docs build for that —
  // emit nothing and move on. Anything else is a real error.
  if (res.stderr.includes('miint_doctest_examples')) {
    console.error('generate-doctests: skipped (extension predates miint_doctest_examples macro)');
    process.exit(0);
  }
  process.stderr.write(`generate-doctests: duckdb exited ${res.status}\n${res.stderr}\n`);
  process.exit(1);
}
const rows = res.stdout.trim() ? JSON.parse(res.stdout.trim()) : [];

// Bucket entries by function name so each function gets one .test file
// (clearer diagnostics on failure than one giant file).
const byFn = new Map();
for (const { function_name, sql: stmt } of rows) {
  if (!byFn.has(function_name)) byFn.set(function_name, []);
  byFn.get(function_name).push(stmt);
}

// Wipe the generated dir so removed/renamed entries don't linger as stale
// test files.
rmSync(OUT_DIR, { recursive: true, force: true });
if (byFn.size === 0) {
  console.error('generate-doctests: registry empty (no functions declare executable_examples yet)');
  process.exit(0);
}
mkdirSync(OUT_DIR, { recursive: true });

// README so future contributors stumbling on this dir know what it is.
writeFileSync(resolve(OUT_DIR, 'README.md'),
  `# Generated doctest .test files\n\n` +
  `This directory is regenerated by \`npm run prebuild\` (which calls\n` +
  `\`site/scripts/generate-doctests.mjs\`). Do not edit by hand — changes\n` +
  `will be wiped on the next prebuild.\n\n` +
  `Each \`doctest_<function_name>.test\` file is one or more sqllogictest\n` +
  `\`statement ok\` blocks built from the C++ \`executable_examples\`\n` +
  `parameter on RegisterDocumented*() calls. To add or remove entries,\n` +
  `edit the C++ registration site and rebuild the extension.\n`);

let count = 0;
for (const [fn, statements] of byFn) {
  const safeName = fn.replace(/[^a-zA-Z0-9_]/g, '_');
  const lines = [
    `# Auto-generated doctest for ${fn}.`,
    `# Source: site/scripts/generate-doctests.mjs from miint_doctest_examples().`,
    `# Edit the executable_examples parameter on the C++ Register call to change.`,
    '',
    'require miint',
    '',
  ];
  for (const stmt of statements) {
    lines.push('statement ok');
    lines.push(stmt.trim().replace(/;$/, '') + ';');
    lines.push('');
  }
  writeFileSync(resolve(OUT_DIR, `doctest_${safeName}.test`), lines.join('\n'));
  count++;
}

console.error(`generate-doctests: wrote ${count} .test files (${rows.length} executable examples)`);
